package com.cedo.botn.networkimport android.content.Contextimport android.location.Locationimport android.util.Logimport com.google.android.gms.location.FusedLocationProviderClientimport com.google.android.gms.location.LocationServicesimport okhttp3.*import okhttp3.MediaType.Companion.toMediaTypeimport okhttp3.RequestBody.Companion.toRequestBodyimport java.io.IOExceptionfun runIntegrationFlow(context: Context) {    // Get the location data    val fusedLocationClient = LocationServices.getFusedLocationProviderClient(context)    fusedLocationClient.lastLocation.addOnSuccessListener { location ->        if (location != null) {            // Run your integration flow with the location            runIoTFlowWithLocation(location)        } else {            Log.e("Location", "No location returned")        }    }.addOnFailureListener {        Log.e("Location", "Error getting location: ${it.message}")    }}fun runIoTFlowWithLocation(location: Location) {    val jsonBody = """        {          "iotReportID": "dummyReportId",          "entities": [            {              "entityID": "b0f65b4e-b83c-451a-8114-84ba7bb1385e",              "entityValue": {                "locationTimestamp": ${System.currentTimeMillis() / 1000},                "advancedGeodeticLocation": {                  "longitude": ${location.longitude},                  "latitude": ${location.latitude},                  "altitude": ${location.altitude},                  "horizontalAccuracy": ${location.accuracy},                  "verticalAccuracy": 3.0,                  "confidenceInAccuracy": 99.9999,                  "bearing": ${location.bearing},                  "speed": ${location.speed}                },                "civicLocation": {                  "country": "MX",                  "state": "CDMX",                  "city": "VCA",                  "street": "Cecilio Robelo 3",                  "longitude": ${location.longitude},                  "latitude": ${location.latitude},                  "addressType": "OTHER",                  "label": "C5 CDMX",                  "formattedAddress": "Cecilio Robelo 3, VCA, CDMX, MX"                }              }            }          ]        }    """.trimIndent()    val client = OkHttpClient()    val requestBody = jsonBody.toRequestBody("application/json".toMediaType())    val request = Request.Builder()        .url("https://iot-service-eu-west-1.carbyneapi.com/IOTService/External-Services/IoTReportEntitiesUpdatesRequest")        .addHeader("Authorization", "Bearer YOUR_IOT_TOKEN")        .addHeader("API-Version", "1")        .addHeader("Content-Type", "application/json")        .post(requestBody)        .build()    client.newCall(request).enqueue(object : Callback {        override fun onFailure(call: Call, e: IOException) {            Log.e("IoTFlow", "Error: ${e.message}")        }        override fun onResponse(call: Call, response: Response) {            val body = response.body?.string()            Log.d("IoTFlow", "Response: $body")        }    })}